import{_ as s,o as i,c as a,ah as t}from"./chunks/framework.ojwJKwrc.js";const k=JSON.parse('{"title":"cocotb and the Celox CLI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cocotb.md","filePath":"guide/cocotb.md"}'),l={name:"guide/cocotb.md"};function n(o,e,h,p,d,c){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="cocotb-and-the-celox-cli" tabindex="-1">cocotb and the Celox CLI <a class="header-anchor" href="#cocotb-and-the-celox-cli" aria-label="Permalink to &quot;cocotb and the Celox CLI&quot;">​</a></h1><p>Celox can compile a Veryl design into a native executable that runs ordinary <a href="https://www.cocotb.org/" target="_blank" rel="noreferrer">cocotb</a> tests through VPI. The generated executable contains the compiled design and the Celox runtime; it does not need the Veryl sources when it runs.</p><h2 id="build-the-cli" tabindex="-1">Build the CLI <a class="header-anchor" href="#build-the-cli" aria-label="Permalink to &quot;Build the CLI&quot;">​</a></h2><p>The CLI is currently built from the Celox source tree:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> celox-vpi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> celox</span></span></code></pre></div><p>Install cocotb into the Python environment you want to use:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cocotb</span></span></code></pre></div><p>The repository dev container already includes cocotb 2.0.1 and Verilator.</p><h2 id="compile-a-design" tabindex="-1">Compile a design <a class="header-anchor" href="#compile-a-design" aria-label="Permalink to &quot;Compile a design&quot;">​</a></h2><p>Pass one source in the Veryl project and name the top-level module:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Top.veryl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/top-sim</span></span></code></pre></div><p>Celox finds <code>Veryl.toml</code> from the source path and includes the project&#39;s source files and dependencies. For a standalone source outside a Veryl project, it compiles that file alone. The output defaults to <code>celox.out</code> when <code>-o</code> is omitted.</p><h2 id="run-cocotb" tabindex="-1">Run cocotb <a class="header-anchor" href="#run-cocotb" aria-label="Permalink to &quot;Run cocotb&quot;">​</a></h2><p>Suppose <code>test/test_top.py</code> contains a cocotb test. Run the generated executable from a directory where that module is importable:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PYTHONPATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> build/top-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test-module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_top</span></span></code></pre></div><p>The executable automatically:</p><ul><li>uses <code>python3</code> and locates its cocotb VPI adapter and libpython;</li><li>supplies the compiled top-level name to cocotb;</li><li>writes <code>results.xml</code> and returns a failing exit status when a test fails.</li></ul><p>Use another Python environment or result path explicitly when needed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">build/top-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --test-module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --results-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/results.xml</span></span></code></pre></div><p><code>--test-filter REGEX</code> selects matching tests; <code>--testcase NAME</code> is also available for cocotb&#39;s legacy test selection. <code>--vpi PATH</code> overrides automatic VPI adapter discovery. The corresponding cocotb environment variables remain supported for existing automation: <code>PYGPI_PYTHON_BIN</code>, <code>LIBPYTHON_LOC</code>, <code>CELOX_COCOTB_VPI</code>, <code>COCOTB_TEST_MODULES</code>, <code>COCOTB_TEST_FILTER</code>, and <code>COCOTB_RESULTS_FILE</code>.</p><h2 id="current-compatibility" tabindex="-1">Current compatibility <a class="header-anchor" href="#current-compatibility" aria-label="Permalink to &quot;Current compatibility&quot;">​</a></h2><p>The compatibility layer covers cocotb 2.0 paths for module and signal discovery, immediate/deposit/force/release writes, scalar and vector values, simulation time, and the Start, ReadWrite, ReadOnly, NextTimeStep, Timer, ValueChange, and End callback regions.</p><p>Packed bit handles, delayed VPI writes, unpacked-array indexing, and derived/cascaded clock scheduling are not yet supported.</p>`,23)])])}const u=s(l,[["render",n]]);export{k as __pageData,u as default};
